    { term: 'Logo ≠ marca', definition: { pt: 'O logo é só UM elemento da marca. A marca é a "nuvem" intangível em volta do produto.', en: 'The logo is just ONE element of the brand. The brand is the intangible "cloud" around the product.' } },
    { term: 'Brandr', definition: { pt: 'Origem alemã de "brand" = queimar; o gado marcado a ferro. Por isso confundem marca com carimbo/logo.', en: 'German origin of "brand" = to burn; cattle branded with an iron. Hence people equate a brand with a stamp/logo.' } },
    { term: 'Brand Value', definition: { pt: 'Valor MONETÁRIO da marca (ativo no balanço; ativos − passivos). Ex: Coca-Cola ~US$98 bi.', en: 'The brand\'s MONETARY worth (asset on the balance sheet; assets − liabilities). E.g. Coca-Cola ~US$98bn.' } },
    { term: 'Brand Equity', definition: { pt: 'Valor INTANGÍVEL na mente do consumidor (percepção/experiência/opinião) que justifica o premium. Ex: +US$2 do talco de marca.', en: 'INTANGIBLE value in the consumer\'s mind (perception/experience/opinion) that justifies the premium. E.g. +US$2 of the branded talc.' } },
    { term: 'Value vs Equity', definition: { pt: 'Value = número no balanço ($). Equity = força na cabeça (🧠). O equity gera o value.', en: 'Value = number on the balance sheet ($). Equity = strength in the head (🧠). Equity generates value.' } },
    { term: 'Brand Awareness', definition: { pt: 'O quanto a marca é reconhecida. "Já ouviu falar?" — diferente de equity ("quão valiosa ela é?").', en: 'How recognised the brand is. "Have you heard of it?" — different from equity ("how valuable is it?").' } },
    { term: 'Brand Associations', definition: { pt: 'O que vem à mente ao pensar na marca: valores, experiências, atributos. 2º pilar de Aaker.', en: 'What comes to mind about the brand: values, experiences, attributes. Aaker\'s 2nd pillar.' } },
    { term: 'Perceived Quality', definition: { pt: 'Qualidade julgada pela experiência com a MARCA, não só pelas features. 3º pilar de Aaker.', en: 'Quality judged by the BRAND experience, not just features. Aaker\'s 3rd pillar.' } },
    { term: 'Brand Loyalty', definition: { pt: 'Lealdade construída por experiências positivas. Topo do equity: gera margem e recompra.', en: 'Loyalty built from positive experiences. Top of equity: drives margin and repeat purchase.' } },
    { term: 'Premium pricing', definition: { pt: 'Cobrar mais pelo mesmo produto graças à marca forte. Equity virando dinheiro.', en: 'Charging more for the same product thanks to a strong brand. Equity turning into money.' } },
    { term: 'Aaker (4 pilares)', definition: { pt: 'Awareness, Associations, Perceived Quality, Loyalty. O modelo de brand equity mais usado.', en: 'Awareness, Associations, Perceived Quality, Loyalty. The most-used brand equity model.' } },
    { term: 'Keller (pirâmide/CBBE)', definition: { pt: 'Brand equity baseado no consumidor: da consciência à ressonância no topo.', en: 'Customer-based brand equity: from awareness up to resonance at the top.' } },
    { term: 'Internal branding', definition: { pt: 'A relação dos funcionários com a marca (orgulho, motivação). Pesquisa da Dra. Lucy. Prévia da Semana 15.', en: 'The employees\' relationship with the brand (pride, motivation). Dr. Lucy\'s research. Preview of Week 15.' } },
    { term: 'Brand Finance Global 500', definition: { pt: 'Ranking anual das 500 marcas mais valiosas por brand value. Em 2022: tech ~US$1,3 tri, TikTok +215%.', en: 'Annual ranking of the 500 most valuable brands by brand value. In 2022: tech ~US$1.3tn, TikTok +215%.' } },
    { term: 'Simon Sinek ("why")', definition: { pt: '"As pessoas não compram o QUE você faz, compram o PORQUÊ." Motor do equity (ex: Apple).', en: '"People don\'t buy what you do, they buy why you do it." The engine of equity (e.g. Apple).' } },
    { term: 'Differentiation (marca)', definition: { pt: 'A marca separa um produto facilmente imitável dos concorrentes. Benefício nº1 do branding.', en: 'The brand separates an easily-imitated product from competitors. Branding\'s nº1 benefit.' } }
